.command-palette-overlay {
  position: fixed;
  inset: 0;
  background: rgb(22 28 31 / 0.4);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 12vh;
  z-index: 60;
}

.command-palette {
  width: min(560px, calc(100vw - 32px));
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-pop);
  overflow: hidden;
}

.command-palette-input {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--theme-border-subtle);
}

.command-palette-input input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  font: inherit;
  font-size: 15px;
  color: var(--theme-text-primary);
}

.command-palette-input kbd {
  font-family: "IBM Plex Mono", ui-monospace, monospace;
  font-size: 11px;
  color: var(--theme-text-muted);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-sm);
  padding: 2px 6px;
  white-space: nowrap;
}

.command-palette-list {
  list-style: none;
  margin: 0;
  padding: 6px;
  max-height: min(420px, 55vh);
  overflow-y: auto;
}

.command-palette-item {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  font: inherit;
  font-size: 14px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  color: var(--theme-text-primary);
  cursor: pointer;
}

.command-palette-item.active,
.command-palette-item:hover {
  background: var(--theme-accent-soft);
  color: var(--theme-accent-ink);
}

.command-palette-item small {
  font-size: 12px;
  color: var(--theme-text-muted);
}

.command-palette-hint {
  padding: 10px;
  font-size: 13px;
  color: var(--theme-text-muted);
}

.command-palette-describe {
  margin: 0;
  padding: 8px 14px 12px;
  font-size: 12px;
  color: var(--theme-text-muted);
  border-top: 1px solid var(--theme-border-subtle);
}

.command-palette-invalid {
  color: var(--theme-danger);
}

/* One graphite body, paired slots and one teal orbit. Real job changes set
 * static poses; no decorative loops, breathing, bounce or rotating spinner. */
.orb {
  display: inline-block;
  vertical-align: middle;
  flex: none;
}
.orb__ring {
  fill: none;
  stroke-width: 1.5;
  opacity: 0;
  transform: rotate(-90deg);
  stroke-dasharray: 30 112;
  stroke-dashoffset: 15;
}
.orb__ribbon {
  fill: none;
  stroke: var(--orb-ribbon);
  stroke-width: 1.5;
  stroke-linecap: square;
}
.orb__ribbon--back {
  stroke: var(--orb-ribbon-soft);
}
.orb__body {
  stroke: var(--orb-edge);
  stroke-width: 0.8;
}
.orb__shade {
  fill: var(--orb-deep);
}
.orb__eyes--joy path {
  fill: none;
  stroke: var(--orb-eye);
  stroke-width: 1.5;
}
.orb__eyes--worry rect,
.orb__eyes--flat rect {
  fill: var(--orb-eye);
}
.orb__eyes--joy,
.orb__eyes--worry,
.orb__eyes--flat {
  visibility: hidden;
}
.orb.is-success .orb__eyes--joy,
.orb.is-error .orb__eyes--worry,
.orb.is-canceled .orb__eyes--flat {
  visibility: visible;
}
.orb.is-success .orb__eyes--open,
.orb.is-error .orb__eyes--open,
.orb.is-canceled .orb__eyes--open {
  visibility: hidden;
}
.orb--s .orb__shade {
  display: none;
}
.orb__eyes,
.orb__ring {
  transform-box: fill-box;
  transform-origin: center;
  transition: transform var(--t-state) var(--ease-in);
}
.orb.is-input .orb__eyes {
  transform: translateY(-1px);
}
.orb.is-queued .orb__eyes {
  transform: scaleY(0.6);
}
.orb.is-thinking .orb__eyes {
  transform: translateX(-1.5px);
}
.orb.is-thinking .orb__ring {
  opacity: 1;
  stroke: var(--interactive);
  stroke-dasharray: 8 134;
}
.orb.is-working .orb__ring {
  opacity: 1;
  stroke: var(--interactive);
  stroke-dasharray: 68 74;
}
.orb.is-waiting .orb__eyes,
.orb.is-approval .orb__eyes {
  transform: translateY(-2px);
}
.orb.is-waiting .orb__ring {
  opacity: 1;
  stroke: var(--interactive);
}
.orb.is-approval .orb__ring,
.orb.is-approval .orb__ribbon {
  opacity: 1;
  stroke: var(--theme-mark);
}
.orb.is-success .orb__ring,
.orb.is-success .orb__ribbon {
  opacity: 1;
  stroke: var(--theme-success);
}
.orb.is-error .orb__ring,
.orb.is-error .orb__ribbon {
  opacity: 1;
  stroke: var(--theme-danger);
}
.orb.is-canceled {
  opacity: 0.55;
}
.bot-figure {
  display: block;
  margin-inline: auto;
}
.bot-figure__body {
  stroke: var(--orb-edge);
  stroke-width: 1;
}
.bot-figure__shade {
  fill: var(--orb-deep);
}
.bot-figure__shadow {
  fill: var(--border-default);
  opacity: 0.24;
}
.bot-figure__ribbon {
  fill: none;
  stroke: var(--orb-ribbon);
  stroke-width: 4;
}
.bot-figure__ribbon--back {
  stroke: var(--orb-ribbon-soft);
}
.bot-figure__eyes {
  transform-box: fill-box;
  transform-origin: center;
  transition: transform var(--t-state) var(--ease-in);
}
.bot-figure.is-thinking .bot-figure__eyes {
  transform: translateX(-4px);
}
.bot-figure.is-waiting .bot-figure__eyes,
.bot-figure.is-approval .bot-figure__eyes {
  transform: translateY(-4px);
}
.bot-figure.is-approval .bot-figure__ribbon {
  stroke: var(--theme-mark);
}
.bot-figure.is-error .bot-figure__ribbon {
  stroke: var(--theme-danger);
}
.bot-figure.is-success .bot-figure__ribbon {
  stroke: var(--theme-success);
}
.bot-figure.is-queued .bot-figure__eyes,
.bot-figure.is-canceled .bot-figure__eyes {
  transform: scaleY(0.6);
}
.bot-figure.is-canceled {
  opacity: 0.55;
}
@media (prefers-reduced-motion: reduce) {
  .orb *,
  .bot-figure * {
    transition: none;
  }
}

