.plan-angle {
  cursor: pointer;
  fill: var(--theme-text-primary);
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.opening-palette {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2);
}
.opening-choice--named,
.projects-page .opening-choice--named {
  border-radius: var(--r-2);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
  height: auto;
  gap: var(--space-2);
  padding: var(--space-2);
  text-align: left;
  font-size: var(--text-xs);
}
.opening-choice--named svg {
  width: 36px;
  height: 36px;
}
.opening-availability {
  margin-top: var(--space-2);
  font-size: var(--text-xs);
  color: var(--theme-text-secondary);
}
.plan-angle:hover {
  fill: var(--theme-accent);
}
.plan-coupling {
  cursor: pointer;
}
.plan-coupling.is-selected {
  stroke: var(--theme-accent);
}
.plan-coupling.has-issue {
  stroke: var(--theme-danger);
}
.plan-issue-flag {
  fill: var(--theme-danger);
  font-weight: 600;
}
.divider-grip {
  fill: var(--theme-text-muted);
  fill-opacity: 0.07;
  outline: none;
  pointer-events: all;
  touch-action: none;
}
.divider-grip.is-vertical {
  cursor: ew-resize;
}
.divider-grip.is-horizontal {
  cursor: ns-resize;
}
.divider-grip:hover,
.divider-grip:active {
  fill: var(--theme-accent);
  fill-opacity: 0.18;
  stroke: var(--theme-accent);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.seam-grip {
  cursor: ew-resize;
  fill: var(--theme-text-muted);
  fill-opacity: 0.06;
  pointer-events: all;
  touch-action: none;
}
.seam-grip:hover {
  fill: var(--theme-accent);
  fill-opacity: 0.14;
}
.seam-grip-dot,
.divider-grip-dots circle {
  fill: var(--theme-text-muted);
  opacity: 0.55;
}
.seam-grip:hover ~ .seam-grip-dot,
.divider-grip:hover ~ .divider-grip-dots circle,
.divider-grip.is-selected ~ .divider-grip-dots circle {
  fill: var(--theme-accent);
  opacity: 1;
}
.divide-preview-line {
  pointer-events: none;
  stroke: var(--theme-accent);
  stroke-dasharray: 14 10;
  stroke-width: 2.5;
  vector-effect: non-scaling-stroke;
}
.front-module.is-divide-target {
  cursor: crosshair;
}
.seam-preview {
  pointer-events: none;
}
.seam-preview-line {
  stroke: var(--theme-accent);
  stroke-dasharray: 16 12;
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
}
.seam-preview-label {
  fill: var(--theme-accent-ink);
  font-family: var(--font-mono);
  font-size: var(--type-display);
  font-variant-numeric: tabular-nums;
}
.assistant-panel__prompt {
  width: 100%;
  box-sizing: border-box;
  resize: vertical;
  border: 1px solid var(--theme-border-strong);
  border-radius: var(--radius-sm);
  background: var(--theme-surface);
  color: var(--theme-text-primary);
  font: inherit;
  padding: 6px 8px;
  margin-bottom: 8px;
}
.assistant-panel__preview,
.alternatives-panel__result {
  border-top: 1px solid var(--theme-border-subtle);
  margin-top: 8px;
  padding-top: 8px;
}
.assistant-panel__notes {
  color: var(--theme-text-secondary);
  font-size: var(--type-dense);
  margin: 0 0 6px;
}
.assistant-panel__ops,
.assistant-panel__rejected {
  margin: 0 0 8px;
  padding-left: 16px;
  font-size: var(--type-dense);
}
.assistant-panel__rejected {
  color: var(--theme-mark);
}
.assistant-panel__meta {
  color: var(--theme-text-muted);
  font-size: var(--type-micro);
  margin: 6px 0 0;
}
.alternatives-panel__cards {
  display: grid;
  gap: 8px;
  margin-bottom: 8px;
}
.alternative-card {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  padding: 8px;
  background: var(--theme-surface);
}
.alternative-card__thumb {
  display: block;
  max-height: 140px;
}
.alternative-card__thumb svg,
.alternative-card__thumb .alternative-card__render {
  display: block;
  width: 100%;
  height: auto;
  min-height: 96px;
  border-radius: var(--radius-sm);
  background: var(--model3d-backdrop, var(--theme-bg-canvas));
}
.alternative-card__label {
  font-weight: 600;
  font-size: var(--type-dense);
  margin: 6px 0 2px;
}
.alternative-card__rationale {
  color: var(--theme-text-secondary);
  font-size: var(--type-micro);
  margin: 0 0 4px;
}
.alternative-card__metrics {
  color: var(--theme-text-muted);
  font-size: var(--type-micro);
  font-variant-numeric: tabular-nums;
  margin: 0;
}
.alternative-card__warnings {
  color: var(--theme-mark);
  font-size: var(--type-micro);
  margin: 4px 0 0;
}
.alternative-card__use {
  margin-top: 6px;
}
.context-menu {
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-pop);
  display: flex;
  flex-direction: column;
  min-width: 200px;
  padding: 4px;
  position: fixed;
  z-index: var(--z-toast);
}
.context-menu__item {
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--theme-text-secondary);
  font: inherit;
  font-size: var(--type-body);
  padding: 7px 10px;
  text-align: left;
}
.context-menu__item:hover {
  background: var(--theme-surface-raised);
  color: var(--theme-text-primary);
}
.context-menu__item--assistant {
  border-top: 1px solid var(--theme-border-subtle);
  border-radius: 0 0 4px 4px;
  color: var(--theme-accent);
  margin-top: 4px;
}
.context-menu__item {
  align-items: center;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.context-menu__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.context-menu__hint {
  background: transparent;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--radius-xs, 3px);
  color: var(--theme-text-muted);
  font-family: var(--font-mono);
  font-size: var(--type-micro);
  padding: 1px 5px;
  white-space: nowrap;
}
.member-mullion.is-selected,
.member-coupler.is-selected {
  stroke: var(--theme-accent);
  stroke-width: 4;
}
.divider-grip.is-selected {
  fill: var(--theme-accent);
  fill-opacity: 0.22;
  stroke: var(--theme-accent);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.joint-hit {
  cursor: pointer;
  fill: transparent;
  pointer-events: all;
}
.joint-hit:hover {
  fill: var(--theme-accent);
  fill-opacity: 0.14;
  stroke: var(--theme-accent);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}
.split-dim,
.member-dim {
  fill: var(--theme-text-muted);
  font-family: var(--font-mono);
  font-size: var(--type-title-l);
  font-variant-numeric: tabular-nums;
  pointer-events: none;
  user-select: none;
}
.prov-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  list-style: none;
  margin: 0 0 10px;
  padding: 0;
}
.prov-chip {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  color: var(--theme-text-secondary);
  font-size: var(--type-micro);
  padding: 1px 8px 1px 3px;
  white-space: nowrap;
}
.prov-chip__state {
  border-radius: var(--r-2);
  font-size: var(--type-micro);
  font-weight: 600;
  letter-spacing: 0.04em;
  margin-right: 4px;
  padding: 1px 6px;
  text-transform: uppercase;
}
.prov-chip--verified .prov-chip__state {
  background: color-mix(in srgb, var(--theme-success) 16%, transparent);
  color: var(--theme-success);
}
.prov-chip--declared .prov-chip__state {
  background: color-mix(in srgb, var(--theme-accent) 14%, transparent);
  color: var(--theme-accent-ink);
}
.prov-chip--unknown .prov-chip__state {
  background: var(--theme-surface-raised);
  color: var(--theme-text-muted);
}
.prov-chip--blocked .prov-chip__state {
  background: color-mix(in srgb, var(--theme-danger) 14%, transparent);
  color: var(--theme-danger);
}
.division-children {
  list-style: none;
  margin: 4px 0 0;
  padding: 0;
}
.division-children li + li {
  margin-top: 2px;
}
.recents {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}
.recents__label {
  color: var(--theme-text-muted);
  font-size: var(--type-micro);
}
.recents__chip {
  background: var(--theme-surface-raised);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  color: var(--theme-text-secondary);
  font-family: var(--font-mono);
  font-size: var(--type-micro);
  max-width: 140px;
  overflow: hidden;
  padding: 2px 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recents__chip:hover {
  border-color: var(--theme-accent);
  color: var(--theme-text-primary);
}
.recents__chip--favorite {
  border-color: color-mix(in srgb, var(--theme-accent) 40%, transparent);
  color: var(--theme-accent-strong, var(--theme-accent));
}
.assembly-field__row {
  align-items: center;
  display: flex;
  gap: 6px;
}
.assembly-field__row select {
  flex: 1;
  min-width: 0;
}
.star-toggle {
  background: transparent;
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  color: var(--theme-text-muted);
  flex: 0 0 auto;
  font-size: var(--type-title-m);
  line-height: 1;
  padding: 5px 7px;
}
.star-toggle:hover:not(:disabled),
.star-toggle.is-active {
  border-color: var(--theme-accent);
  color: var(--theme-accent);
}
.star-toggle:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}
.issue-fix {
  background: transparent;
  border: none;
  color: var(--theme-accent);
  font-size: var(--type-micro);
  margin-top: 2px;
  padding: 0 4px;
  text-align: left;
}
.issue-fix:hover {
  text-decoration: underline;
}
.section-view {
  display: block;
  height: auto;
  margin-top: 0.5rem;
  width: 100%;
}
.section-member {
  fill: var(--member-pvc-fill);
  stroke: var(--member-pvc-edge);
  stroke-width: 0.6;
}
.section-member--aluminium {
  fill: var(--member-aluminium-fill);
  stroke: var(--member-aluminium-edge);
}
.section-member--approx {
  fill: none;
  stroke-dasharray: 3 2;
}
.section-glass {
  fill: var(--model3d-glass);
  opacity: 0.75;
}
.section-gasket {
  fill: var(--model3d-gasket);
}
.section-dim {
  stroke: var(--theme-text-muted);
  stroke-width: 0.5;
}
.section-dim__arrow {
  fill: var(--theme-text-muted);
}
.section-dim__text {
  fill: var(--theme-text-muted);
  font-size: var(--type-micro);
}
.section-label {
  fill: var(--theme-text-muted);
  font-size: var(--type-micro);
  letter-spacing: 0.12em;
}
.section-approx {
  fill: var(--theme-warning);
  font-size: var(--type-micro);
}
.section-break {
  fill: none;
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
}
.module-frameless .module-glass {
  stroke: var(--theme-border-strong);
}
.frameless-exposed {
  fill: var(--theme-bg-canvas);
  stroke: none;
  opacity: 0.35;
}
.frameless-channel {
  fill: var(--model3d-steel);
  stroke: var(--theme-text-muted);
  stroke-width: 1.2;
  vector-effect: non-scaling-stroke;
}
.frameless-clamp,
.frameless-fitting {
  fill: var(--model3d-steel);
  stroke: var(--theme-text-primary);
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}
.frameless-fitting--patch_fitting,
.frameless-fitting--clamp {
  fill: var(--member-aluminium-edge);
}
.frameless-fitting--hinge,
.frameless-fitting--lock {
  fill: var(--theme-text-secondary);
}
.frameless-seal {
  fill: none;
  stroke: var(--theme-text-muted);
  stroke-dasharray: 10 6;
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}
.sliding-track {
  stroke: var(--theme-text-muted);
  stroke-width: 1.6;
  stroke-dasharray: 7 5;
  vector-effect: non-scaling-stroke;
}
.sliding-arrow {
  fill: none;
  stroke: var(--theme-text-primary);
  stroke-width: 1.5;
  stroke-linecap: square;
  stroke-linejoin: miter;
  vector-effect: non-scaling-stroke;
}
/* CAD workspace: the drawing owns the available area; the tree is a flyout. */
.assembly-editor,
.assembly-editor--tree-closed {
  display: grid;
  position: relative;
  height: calc(100dvh - 110px);
  min-height: 0;
  grid-template-columns: 112px minmax(0, 1fr) 320px;
  grid-template-rows: minmax(0, 1fr) 28px;
  grid-template-areas: "tools canvas side" "tools status side";
  gap: var(--space-2);
  min-width: 0;
}
.assembly-canvas {
  display: flex;
  flex-direction: column;
  min-width: 0;
  border: none;
  background: var(--bg-app);
}
.assembly-view-choices {
  position: absolute;
  top: var(--space-3);
  left: var(--space-3);
  z-index: var(--z-rail);
  background: var(--surface-panel);
  padding: var(--space-1);
  border: 1px solid var(--border-default);
}
.assembly-editor .canvas-viewport {
  min-height: 0;
  flex: 1;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  background: var(--surface-sheet);
  border-radius: var(--r-0);
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 0 100%);
}
.assembly-tools {
  align-items: stretch;
  border-radius: var(--r-0);
  padding: var(--space-1);
  gap: var(--space-1);
}
.assembly-tools .tool-button {
  width: 100%;
  min-height: 44px;
  height: auto;
  justify-content: flex-start;
  gap: var(--space-1);
  font-size: var(--type-label);
  text-align: left;
  padding: var(--space-1);
}
.tool-button .tool-icon {
  flex: 0 0 24px;
  width: 24px;
  height: 24px;
  stroke-width: 1.5;
  stroke-linecap: square;
  stroke-linejoin: miter;
}
.tool-button .tool-icon path {
  vector-effect: non-scaling-stroke;
}
.tool-button kbd {
  margin-left: auto;
  font-size: var(--type-micro);
}
.assembly-tools__divider {
  width: 100%;
}
.assembly-tree {
  position: absolute;
  grid-area: auto;
  left: 120px;
  bottom: 32px;
  top: auto;
  width: 280px;
  max-width: calc(100% - 128px);
  max-height: 60%;
  z-index: var(--z-popover);
  background: var(--surface-panel);
  border: 1px solid var(--border-default);
  overflow: auto;
  box-shadow: var(--e2);
}
.assembly-side {
  background: var(--surface-panel);
  border-left: 1px solid var(--border-default);
  gap: var(--space-2);
}
.editor-inspector-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-2) var(--space-3) 0;
}
.editor-inspector-header h3,
.position-editor .editor-inspector-header h3 {
  margin: 0;
  font-size: var(--type-title-m);
}
.editor-inspector-header button {
  display: none;
}
.assembly-inspector {
  border: none;
  background: transparent;
  padding: var(--space-2) var(--space-3);
  gap: var(--space-2);
}
.assembly-inspector__header h4 {
  font-size: var(--type-title-m);
}
.assembly-inspector .inspector-section {
  display: block;
}
.inspector-section > summary {
  font-size: var(--type-label);
  padding-block: var(--space-1);
}
.position-editor .assembly-inspector .assembly-field {
  display: flex;
  min-height: 28px;
  justify-content: space-between;
  gap: var(--space-2);
  margin-block: var(--space-1);
}
.assembly-inspector .assembly-field > span:first-child {
  font-size: var(--type-dense);
}
.position-editor .assembly-inspector .assembly-field input {
  box-sizing: border-box;
  font-family: var(--font-mono);
  min-height: 28px;
  height: 28px;
  padding: var(--space-1) 32px var(--space-1) var(--space-1);
  width: 112px;
  max-width: 100%;
}
.position-editor .assembly-inspector .assembly-field select {
  box-sizing: border-box;
  max-width: 196px;
  width: 196px;
  min-height: 28px;
  height: 28px;
  padding: var(--space-1);
  font-size: var(--type-dense);
}
.editor-opening-trigger,
.position-editor .editor-opening-trigger {
  display: flex;
  flex-direction: column;
  width: 100%;
  gap: var(--space-1);
  text-align: left;
  font-size: var(--type-dense);
  min-height: 32px;
  padding: var(--space-1) var(--space-2);
}
.editor-opening-trigger > span:first-child {
  color: var(--text-secondary);
}
.assembly-inspector > .inspector-section:has(.editor-opening-trigger) > summary,
.assembly-inspector > .inspector-section:has(.glass-selector--compact) > summary {
  display: none;
}
.assembly-inspector .ui-popover-anchor {
  display: block;
  width: 100%;
}
.position-editor .assembly-inspector .editor-opening-trigger {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  width: 100%;
  min-height: 28px;
  padding: var(--space-1);
}
.editor-opening-trigger > span:last-child {
  min-width: 0;
  overflow-wrap: anywhere;
}
.assembly-inspector .glass-selector--compact .glass-help {
  margin: var(--space-1) 0;
  font-size: var(--type-micro);
}
.assembly-inspector .glass-selector--compact > details > summary {
  font-size: var(--type-micro);
  margin-block: var(--space-1);
}
.editor-basic-dimensions {
  display: grid;
  gap: var(--space-1);
}
.editor-leaf-facts {
  margin: 0;
  font-size: var(--type-dense);
}
.editor-leaf-facts > div {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: var(--space-2);
  min-height: 28px;
}
.editor-leaf-facts dt {
  color: var(--text-secondary);
}
.editor-leaf-facts dd,
.position-editor .editor-leaf-facts dd {
  margin: 0;
  text-align: right;
  max-width: 196px;
  overflow-wrap: anywhere;
  font-family: var(--font-mono);
}
.editor-leaf-facts__source {
  margin-block: var(--space-1);
  font-size: var(--type-micro);
}
.editor-calculation-note {
  margin: 0;
  padding-inline: var(--space-3);
  color: var(--text-secondary);
  font-size: var(--type-dense);
}
.assembly-inspector .assembly-unit {
  font-size: var(--type-micro);
  right: var(--space-2);
}
.position-editor .assembly-inspector .glass-field {
  margin-block: var(--space-1);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.position-editor .assembly-inspector .glass-field select {
  width: 196px;
  min-width: 0;
  height: 28px;
  font-size: var(--type-dense);
  padding: var(--space-1);
}
.position-editor .assembly-inspector .glass-selector--compact {
  margin: 0;
  border: 0;
}
.position-editor .detail-levels__btn {
  padding: var(--space-1);
  font-size: var(--type-dense);
}
.assembly-side .detail-levels {
  padding-inline: var(--space-3);
}
.editor-flyout {
  position: absolute;
  left: 120px;
  top: var(--space-2);
  z-index: var(--z-popover);
  width: min(520px, calc(100% - 136px));
  max-height: calc(100% - 48px);
  overflow-y: auto;
  box-sizing: border-box;
  background: var(--surface-panel);
  border: 1px solid var(--border-default);
  border-radius: var(--r-2);
  padding: var(--space-3);
  box-shadow: var(--e2);
}
.editor-flyout > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  margin-bottom: var(--space-2);
}
.editor-flyout h3,
.editor-proposal h3 {
  font-size: var(--type-title-m);
  margin: 0;
}
.editor-flyout > header button {
  min-width: 32px;
  height: 32px;
}
.editor-missing {
  left: auto;
  right: var(--space-2);
}
.editor-shortcuts {
  margin: 0;
}
.editor-shortcuts > div {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  padding-block: var(--space-1);
}
.editor-shortcuts dd {
  margin: 0;
}
.editor-library .starter-gallery {
  display: block;
  overflow: visible;
  padding: 0;
}
.starter-family h4 {
  margin: var(--space-3) 0 var(--space-2);
  font-size: var(--type-label);
  text-transform: uppercase;
}
.starter-family > div {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-2);
}
.editor-library .starter-card {
  min-width: 0;
  width: 100%;
}
.editor-library .starter-thumb {
  height: 96px;
}
.editor-library .starter-thumb [role="button"],
.editor-library .starter-thumb foreignObject {
  display: none;
}
.editor-library .starter-search input {
  width: 100%;
  box-sizing: border-box;
}
.editor-assistant {
  padding: var(--space-3);
  border-top: 1px solid var(--border-default);
}
.editor-assistant > summary {
  cursor: pointer;
}
.editor-operation-message {
  position: absolute;
  bottom: 32px;
  left: 128px;
  z-index: var(--z-rail);
  max-width: calc(100% - 464px);
  padding: var(--space-2);
  background: var(--surface-panel);
  border: 1px solid var(--border-default);
}
.editor-proposal {
  position: absolute;
  left: var(--space-3);
  bottom: 56px;
  width: min(400px, calc(100% - 32px));
  box-sizing: border-box;
  z-index: var(--z-rail);
  padding: var(--space-3);
  background: var(--surface-panel);
  border: 1px solid var(--mark);
}
.editor-proposal p {
  margin-block: var(--space-2);
}
.editor-proposal-price {
  font-family: var(--font-mono);
}
.editor-proposal button {
  margin-right: var(--space-2);
}
.command-ghost :is(path, polyline, line, rect) {
  fill: none;
  stroke: var(--mark);
  stroke-dasharray: 8 5;
  stroke-width: 1.5px;
  vector-effect: non-scaling-stroke;
}
.command-ghost text {
  fill: var(--state-person-ink);
}
.viewport-island {
  background: var(--surface-panel);
}
.viewport-button--fit {
  gap: var(--space-1);
}
.assembly-statusbar {
  min-width: 0;
  font-size: var(--type-micro);
}
.assembly-statusbar__dims {
  white-space: nowrap;
}
.assembly-statusbar .assembly-status {
  margin: 0;
  padding: 0;
  border: 0;
  font-size: var(--type-micro);
}
.plan-inset {
  width: min(240px, 30%);
  height: 120px;
  right: var(--space-3);
  bottom: 48px;
  box-shadow: var(--e2);
}
.model3d-inset {
  width: min(480px, calc(100% - 32px));
  max-height: calc(100% - 80px);
}
.assembly-side .glass-selector {
  padding: 0;
}
.assembly-side .hardware-panel {
  margin: 0;
  padding: 0;
  border: none;
}
.assembly-side .hardware-panel h5 {
  margin: 0 0 var(--space-1);
  font-size: var(--type-label);
}
.assembly-side .hardware-class {
  margin-block: var(--space-1);
}
.assembly-side .hardware-panel p {
  margin-block: var(--space-1);
  font-size: var(--type-dense);
}
@media (max-width: 1279px) {
  .assembly-editor,
  .assembly-editor--tree-closed {
    grid-template-columns: 48px minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) 28px;
    grid-template-areas: "tools canvas" "tools status";
  }
  .assembly-tools .tool-button {
    justify-content: center;
  }
  .assembly-tools .tool-button :is(span, kbd) {
    display: none;
  }
  .assembly-side {
    display: none;
  }
  .assembly-side.is-open {
    display: flex;
    position: absolute;
    right: 0;
    top: 0;
    bottom: 0;
    width: 320px;
    z-index: var(--z-drawer);
    box-shadow: var(--e2);
  }
  .editor-inspector-header button {
    display: block;
  }
  .editor-flyout {
    left: 56px;
    width: min(520px, calc(100% - 64px));
  }
  .editor-missing {
    left: auto;
    right: var(--space-2);
  }
  .assembly-tree {
    left: 56px;
  }
  .editor-operation-message {
    left: 64px;
    max-width: calc(100% - 80px);
  }
}
@media (max-width: 1023px) {
  .assembly-editor,
  .assembly-editor--tree-closed {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: "canvas" "status";
  }
  .assembly-tools {
    display: none;
  }
  .editor-library {
    display: none;
  }
  .assembly-canvas .model3d-toggle {
    display: none;
  }
}

.operation-preview {
  border-top: 1px solid var(--border-default);
  padding-block: var(--space-2);
  font-size: var(--type-body);
}
.operation-preview__view {
  color: var(--text-small-muted);
}
.operation-preview__drawings {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2);
}
.operation-preview figure {
  margin: 0;
  padding: var(--space-2);
  border: 1px solid var(--border-default);
  min-width: 0;
  background: var(--surface-sheet);
}
.operation-preview figcaption {
  font-weight: 600;
}
.operation-preview .product-front-svg {
  width: 100%;
  height: 140px;
  background: var(--canvas-sheet);
}
.operation-preview__dimensions,
.operation-preview__prices dd {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.operation-preview__prices {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: var(--space-1) var(--space-2);
}
.operation-preview__prices dd {
  margin: 0;
}
.operation-preview pre {
  max-height: 160px;
  overflow: auto;
}
.operation-project__changes {
  padding-left: var(--space-4);
}
.operation-project__changes > li > p {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.operation-project .ask-dock__action {
  border-radius: var(--r-1);
}
.ask-dock__questions[aria-label="Aclaración del trabajo"] .ask-dock__chip {
  border-radius: var(--r-1);
}
.operation-project button:focus-visible,
.operation-preview summary:focus-visible,
.ask-dock__questions[aria-label="Aclaración del trabajo"] button:focus-visible {
  outline: var(--space-2px) solid var(--border-focus);
  outline-offset: var(--space-2px);
}

/* Contextual Ask dock — a floating panel over the workspace corner. The
 * trigger is one quiet affordance; the panel keeps the thread inside the
 * current surface's context. */
.ask-dock {
  position: fixed;
  right: 16px;
  bottom: 40px; /* above the status bar */
  z-index: 60;
}
/* On the position editor the bottom-right corner is the inspector column —
 * and just left of it the canvas' .plan-inset/.viewport-status live. The
 * dock slides left of the inspector rail so neither is covered. */
.ask-dock--canvas {
  right: 316px;
}
.ask-dock__trigger {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 0;
  background: transparent;
  cursor: pointer;
  padding: 0;
  display: grid;
  place-items: center;
  /* The orb carries its own presence — the button is only a hit target. */
  filter: drop-shadow(0 6px 14px rgb(9 14 13 / 28%));
  transition:
    transform 0.18s ease,
    filter 0.18s ease;
}
.ask-dock__trigger:hover {
  transform: translateY(-2px) scale(1.04);
  filter: drop-shadow(0 10px 18px rgb(9 14 13 / 34%));
}
.ask-dock__trigger:focus-visible {
  outline: 2px solid var(--theme-accent, #0f817a);
  outline-offset: 3px;
}
.ask-dock__panel {
  width: 340px;
  max-height: 480px;
  display: flex;
  flex-direction: column;
  background: var(--theme-surface-panel, #ffffff);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  box-shadow: 0 8px 32px rgb(0 0 0 / 18%);
  overflow: hidden;
}
.ask-dock__header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--theme-border-subtle, #d9dfde);
}
.ask-dock__title {
  font-weight: 600;
  font-size: 13px;
  flex: 1;
}
.ask-dock__surface {
  font-size: 11px;
  color: var(--theme-text-muted, #5c6c68);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 999px;
  padding: 1px 8px;
}
.ask-dock__close {
  border: 0;
  background: none;
  font-size: 18px;
  cursor: pointer;
  color: var(--theme-text-muted, #5c6c68);
}
.ask-dock__thread {
  flex: 1;
  overflow-y: auto;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 80px;
}
.ask-dock__hint {
  color: var(--theme-text-muted, #5c6c68);
  font-size: 12.5px;
  margin: 6px 0;
}
.ask-dock__turn {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.ask-dock__question {
  font-size: 12.5px;
  font-weight: 600;
  margin: 0;
}
.ask-dock__answer {
  font-size: 12.5px;
  margin: 0;
  white-space: pre-wrap;
}
.ask-dock__warnings {
  margin: 0;
  padding-left: 16px;
  font-size: 12px;
  color: var(--theme-warning, #b25e09);
}
.ask-dock__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.ask-dock__action {
  font-size: 12px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-accent-soft, #e4f3f1);
  border-radius: 999px;
  padding: 3px 10px;
  cursor: pointer;
}
.ask-dock__meta {
  font-size: 10.5px;
  color: var(--theme-text-muted, #5c6c68);
  margin: 2px 0 0;
}
.ask-dock__busy {
  font-size: 12px;
  color: var(--theme-text-muted, #5c6c68);
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.ask-dock__error {
  font-size: 12px;
  color: var(--theme-danger, #b3372f);
  margin: 0;
  padding: 0 10px 6px;
}
.ask-dock__offline {
  font-size: 12px;
  color: var(--theme-text-secondary, #4b5f5c);
  background: var(--theme-warning-soft, #fdf3e3);
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  margin: 0;
  padding: 6px 10px;
}
.ask-dock__chips {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px 0;
}
.ask-dock__chip {
  font-size: 11.5px;
  text-align: left;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-panel, #ffffff);
  color: var(--theme-text-secondary, #33443f);
  border-radius: 8px;
  padding: 5px 10px;
  cursor: pointer;
}
.ask-dock__chip:hover {
  border-color: var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
}
.ask-dock__pending {
  margin: 0;
  padding: 6px 10px;
  list-style: none;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  font-size: 12px;
  color: var(--theme-text-secondary, #57635f);
}
.ask-dock__pending li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 3px 0;
}
.ask-dock__pending li span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ask-dock__pending li button {
  border: 0;
  background: transparent;
  color: var(--theme-text-tertiary, #8a948f);
  cursor: pointer;
  font-size: 13px;
  padding: 0 4px;
}
.ask-dock__form {
  display: flex;
  gap: 6px;
  padding: 8px 10px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
}
.ask-dock__form input {
  flex: 1;
  font-size: 13px;
  padding: 7px 10px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #ffffff);
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__form button {
  font-size: 13px;
  padding: 7px 14px;
  border: 0;
  border-radius: 8px;
  background: var(--theme-accent, #0f817a);
  color: var(--theme-surface-panel);
  cursor: pointer;
}
.ask-dock__form button:disabled {
  opacity: 0.5;
  cursor: default;
}
.ask-dock__modes {
  display: inline-flex;
  gap: 2px;
  margin-left: 6px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  padding: 1px;
}
.ask-dock__mode {
  font-size: 11px;
  padding: 2px 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--theme-text-secondary, #576664);
  cursor: pointer;
}
.ask-dock__mode--active {
  background: var(--theme-accent, #0f817a);
  color: var(--theme-surface-panel);
}
.ask-dock__queries {
  margin: 4px 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.ask-dock__queries li {
  font-size: 10.5px;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--theme-surface-inset, #f0f4f3);
  color: var(--theme-text-secondary, #576664);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
}
.ask-dock__ops {
  display: flex;
  flex-direction: column;
  gap: 4px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  padding: 6px 8px;
}
.ask-dock__ops ul {
  margin: 0;
  padding-left: 16px;
  font-size: 12px;
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__ops .ask-dock__action {
  align-self: flex-start;
}
.ask-dock__action--prepare {
  border: 1px solid var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
}

/* §08-WC batch edit diff — one row per affected position, applied through
   the canonical save after the human confirms. */
.ask-dock__batch ul {
  padding-left: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
}
.ask-dock__batch-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 4px 10px;
  align-items: baseline;
  padding: 3px 0;
  border-top: 1px dashed var(--theme-border-subtle, #d9dfde);
}
.ask-dock__batch-row:first-child {
  border-top: 0;
}
.ask-dock__batch-where {
  font-weight: 600;
  white-space: nowrap;
}
.ask-dock__batch-ops {
  color: var(--theme-text-secondary, #576664);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ask-dock__batch-cost {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.ask-dock__batch-row.is-applied .ask-dock__batch-cost {
  color: var(--theme-accent, #0f817a);
  font-weight: 600;
}
.ask-dock__batch-row.is-failed .ask-dock__batch-cost,
.ask-dock__batch-row.is-apply_failed .ask-dock__batch-cost {
  color: var(--theme-danger, #b3261e);
}
.ask-dock__batch-row.is-unsupported {
  color: var(--theme-text-muted, #8a9493);
}
.ask-dock__batch-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  padding-top: 6px;
  font-size: 12px;
  color: var(--theme-text-secondary, #576664);
}
.ask-dock__form textarea {
  flex: 1;
  font-size: 13px;
  padding: 7px 10px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #ffffff);
  color: var(--theme-text-primary, #1f2a29);
  resize: none;
  font-family: inherit;
}

/* ---- §07-H assistant workspace ----------------------------------- */
.aiws {
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr) 300px;
  gap: 0;
  /* The workspace IS the window: bounded to the viewport minus the 46px
   * topbar and the .workspace padding (1.5rem × 2) so the transcript scrolls
   * inside — never the page, which would scroll the composer and rail off. */
  height: calc(100vh - 46px - 3rem);
  min-height: 0;
}
.aiws-rail {
  border-right: 1px solid var(--theme-border-subtle, #d9dfde);
  overflow-y: auto;
  padding: 12px;
}
.aiws-rail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
.aiws-rail__head h2 {
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--theme-text-secondary, #4b5f5c);
  margin: 0;
}
.aiws-joblist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.aiws-job {
  width: 100%;
  text-align: left;
  border: 1px solid transparent;
  background: none;
  border-radius: var(--r-1);
  padding: var(--space-2) var(--space-3);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.aiws-job:hover {
  background: var(--theme-surface-raised, #f2f5f4);
}
.aiws-job--active {
  border-color: var(--theme-accent, #0f817a);
  background: var(--theme-accent-ghost, rgba(15, 129, 122, 0.08));
}
.aiws-job__goal {
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.aiws-job__meta {
  font-size: 11px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-state {
  display: inline-block;
  font-size: var(--type-label);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 1px 6px;
  border-radius: var(--r-1);
  background: var(--theme-surface-raised, #f2f5f4);
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-state[data-state="running"],
.aiws-state[data-state="queued"],
.aiws-state[data-state="planning"] {
  background: var(--theme-accent-ghost, rgba(15, 129, 122, 0.12));
  color: var(--theme-accent-deep);
}
.aiws-state[data-state="waiting-for-user"],
.aiws-state[data-state="waiting-for-approval"] {
  background: rgba(196, 141, 41, 0.15);
  color: var(--theme-warning);
}
.aiws-state[data-state="succeeded"] {
  background: rgba(46, 125, 79, 0.14);
  color: var(--theme-success);
}
.aiws-state[data-state="failed"],
.aiws-state[data-state="failed-retryable"] {
  background: rgba(180, 45, 45, 0.12);
  color: var(--theme-danger);
}
.aiws-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.aiws-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--theme-border-subtle, #d9dfde);
}
.aiws-head > div {
  flex: 1;
}
.aiws-head h1 {
  font-size: 15px;
  margin: 0 0 4px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-head__meta {
  font-size: 11px;
  color: var(--theme-text-secondary, #4b5f5c);
  margin: 0;
}
.aiws-transcript {
  flex: 1;
  overflow-y: auto;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.aiws-turn--user {
  align-self: flex-end;
  max-width: 72%;
  background: var(--theme-accent-ghost, rgba(15, 129, 122, 0.1));
  border-radius: 12px 12px 4px 12px;
  padding: 8px 12px;
  margin: 0;
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
  white-space: pre-wrap;
}
.aiws-turn--agent {
  max-width: 84%;
  display: flex;
  align-items: flex-start;
  gap: 9px;
}
.aiws-turn--agent .orb {
  margin-top: 1px;
}
.aiws-turn__body {
  flex: 1;
  min-width: 0;
}
.aiws-plan {
  margin: 0 0 8px;
  padding-left: 20px;
  font-size: 12px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-reply {
  margin: 0;
  font-size: 14px;
  line-height: 1.5;
  color: var(--theme-text-primary, #1f2a29);
  white-space: pre-wrap;
}
.aiws-questions {
  margin-top: 8px;
  padding: 8px 12px;
  border-left: 3px solid var(--theme-warning);
  background: rgba(196, 141, 41, 0.08);
  border-radius: 0 8px 8px 0;
}
.aiws-questions p {
  margin: 0;
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-warnings {
  margin: 8px 0 0;
  padding-left: 18px;
  font-size: 12px;
  color: var(--theme-danger);
}
.aiws-toggle {
  margin-top: 8px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-raised, #f2f5f4);
  border-radius: 999px;
  font-size: 11px;
  padding: 3px 10px;
  cursor: pointer;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-work {
  margin-top: 6px;
  font-size: 12px;
  color: var(--theme-text-secondary, #4b5f5c);
  border-left: 2px solid var(--theme-border-subtle, #d9dfde);
  padding-left: 10px;
}
.aiws-work ul {
  margin: 4px 0;
  padding-left: 16px;
}
.aiws-claims small {
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-steps {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.aiws-action {
  border: 1px solid var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
  background: none;
  border-radius: 999px;
  font-size: 11px;
  padding: 4px 12px;
  cursor: pointer;
}
.aiws-action--static {
  border-color: var(--theme-border-subtle, #d9dfde);
  color: var(--theme-text-secondary, #4b5f5c);
  cursor: default;
}
.aiws-artifacts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
.aiws-artifact {
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-panel, #fff);
  border-radius: 10px;
  padding: 8px 12px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: left;
}
.aiws-artifact:hover {
  border-color: var(--theme-accent, #0f817a);
}
.aiws-artifact strong {
  font-size: 12px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-artifact small {
  font-size: 10px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-live {
  font-size: 12px;
  color: var(--theme-accent, #0f817a);
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}
.aiws-hero {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 8px;
}
.aiws-hero__title {
  font-size: var(--text-title);
  font-weight: 600;
  margin: 0 0 4px;
}
.aiws-error {
  margin: 0 18px 8px;
  font-size: 12px;
  color: var(--theme-danger);
}
.aiws-composer {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  flex-wrap: wrap;
  padding: 12px 18px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
}
.aiws-composer .orb {
  align-self: center;
  flex-shrink: 0;
}
.aiws-composer select {
  font-size: 12px;
  padding: 6px 8px;
  max-width: 11rem;
  min-width: 0;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #fff);
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-composer textarea {
  flex: 1 1 10rem;
  min-width: 0;
  font-size: 13px;
  padding: 8px 10px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 8px;
  background: var(--theme-surface-panel, #fff);
  color: var(--theme-text-primary, #1f2a29);
  resize: none;
  font-family: inherit;
}
.aiws-inspector {
  border-left: 1px solid var(--theme-border-subtle, #d9dfde);
  overflow-y: auto;
  padding: 14px;
}
.aiws-artifact-detail h2 {
  font-size: 13px;
  margin: 0 0 4px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-evidence {
  font-size: 11px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-payload {
  font-size: 11px;
  background: var(--theme-surface-raised, #f2f5f4);
  border-radius: 8px;
  padding: 10px;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-word;
}
.aiws-empty {
  font-size: 13px;
  color: var(--theme-text-tertiary, #7b8a88);
  padding: 8px;
}
@media (max-width: 1100px) {
  .aiws {
    grid-template-columns: 210px minmax(0, 1fr);
  }
  .aiws-inspector {
    display: none;
  }
}

.aiws-tool {
  display: inline-block;
  margin-right: 6px;
  padding: 0 6px;
  border: 1px solid var(--line-strong, #d0d5dd);
  border-radius: 4px;
  background: var(--surface-sunken, #f2f4f7);
  color: var(--text-subtle, #667085);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10.5px;
  font-weight: 500;
}
.aiws-action .aiws-tool {
  margin-right: 0;
  margin-left: 6px;
}

/* §08 measurement — apply/decline pair + workspace metrics strip. */
.ask-dock__ops-actions {
  display: flex;
  gap: 6px;
  align-items: center;
}
.ask-dock__ops-actions .ask-dock__action {
  align-self: auto;
}
.ask-dock__action--ghost {
  background: transparent;
  color: var(--theme-text-secondary, #576664);
  border-style: dashed;
}
.aiws-metrics {
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 12px;
  background: var(--theme-surface-panel, #ffffff);
}
.aiws-metrics h2 {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--theme-text-secondary, #576664);
  margin: 0 0 8px;
  display: flex;
  gap: 8px;
  align-items: baseline;
}
.aiws-metrics h2 small {
  font-weight: 400;
  text-transform: none;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-metrics dl {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 8px 12px;
  margin: 0;
}
.aiws-metrics dl > div {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.aiws-metrics dt {
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-metrics dd {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--theme-text-primary, #1f2a29);
  font-variant-numeric: tabular-nums;
}
.aiws-metrics__failure {
  margin: 8px 0 0;
  font-size: 11px;
  color: var(--theme-danger, #b3372f);
}

.aiws-head__actions {
  display: flex;
  flex-shrink: 0;
  gap: 0.5rem;
  margin-left: auto;
}

/* ——— Artifact chips in the dock ——— */
.ask-dock__artifacts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.ask-dock__artifact {
  border: 1px solid var(--theme-accent, #0f817a);
  color: var(--theme-accent, #0f817a);
  background: var(--theme-accent-soft, #e4f3f1);
  border-radius: 999px;
  font-size: 11px;
  padding: 3px 10px;
  cursor: pointer;
}

/* ——— Typed artifact rendering (workspace inspector) ——— */
.art {
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.art-message .art-field {
  display: flex;
  gap: 8px;
  margin: 0 0 4px;
  font-size: 12px;
}
.art-message .art-field span {
  color: var(--theme-text-tertiary, #7b8a88);
  min-width: 52px;
}
.art-body {
  margin: 8px 0 0;
  padding: 10px 12px;
  background: var(--theme-surface-raised, #f2f5f4);
  border-radius: 8px;
  white-space: pre-wrap;
  font-size: 12.5px;
  line-height: 1.5;
}
.art-checklist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.art-checklist li {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.art-checklist small {
  color: var(--theme-text-tertiary, #7b8a88);
}
.art-pill {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-radius: 999px;
  padding: 1px 8px;
  flex: none;
}
.art-pill[data-tone="ok"] {
  background: var(--theme-success-soft, #e3f2ea);
  color: var(--theme-success, #1e7a4c);
}
.art-pill[data-tone="bad"] {
  background: var(--theme-danger-soft, #fbe9e7);
  color: var(--theme-danger, #b3372f);
}
.art-pill[data-tone="warn"] {
  background: var(--theme-warning-soft, #fdf1e3);
  color: var(--theme-warning, #9c5306);
}
.art-totals {
  display: flex;
  gap: 14px;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--theme-border-subtle, #d9dfde);
  font-size: 12px;
}
.art-group {
  margin-bottom: 12px;
}
.art-group h3,
.art-group-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--theme-text-secondary, #4b5f5c);
  margin: 0 0 6px;
}
.art-count {
  color: var(--theme-text-tertiary, #7b8a88);
}
.art-lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.art-lines li {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.art-lines li small,
.art-lines li span {
  color: var(--theme-text-secondary, #4b5f5c);
}
.art-lines--numbered {
  list-style: decimal;
  padding-left: 18px;
}
.art-line-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.art-note {
  margin: 6px 0 0;
  font-size: 11.5px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.art-kv {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.art-kv-row {
  display: grid;
  grid-template-columns: minmax(90px, 140px) 1fr;
  gap: 8px;
  font-size: 12px;
  align-items: baseline;
}
.art-kv-row dt {
  color: var(--theme-text-secondary, #4b5f5c);
  text-transform: capitalize;
}
.art-kv-row dd {
  margin: 0;
}
.art-empty {
  margin: 0;
  color: var(--theme-text-tertiary, #7b8a88);
  font-size: 12px;
}

/* --- live run progress, waiting banner, artifact shelf, rail identity --- */
.aiws-progress {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 18px;
  padding: 7px 12px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  background: var(--theme-surface-panel, #fff);
}
.aiws-progress__label {
  font-size: 11.5px;
  color: var(--theme-text-secondary, #4b5f5c);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.aiws-waiting {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 18px;
  padding: 10px 14px;
  border: 1px solid var(--theme-warning, #c48d29);
  border-radius: 10px;
  background: rgba(196, 141, 41, 0.08);
  font-size: 13px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-shelf {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin: 0 18px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--theme-border-subtle, #d9dfde);
}
.aiws-shelf__label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--theme-text-tertiary, #7b8a88);
}
.aiws-shelf__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  background: var(--theme-surface-panel, #fff);
  border-radius: 999px;
  padding: 4px 12px 4px 6px;
  font-size: 12px;
  cursor: pointer;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-shelf__item:hover {
  border-color: var(--theme-accent, #0f817a);
}
.aiws-job {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.aiws-job .orb {
  margin-top: 2px;
}
.aiws-job__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  text-align: left;
}
.aiws-replay {
  display: inline-block;
  margin-left: 8px;
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 999px;
  padding: 0 8px;
}
.aiws-turn--error {
  max-width: 84%;
  display: flex;
  align-items: flex-start;
  gap: 9px;
}
.aiws-error__text {
  margin: 0;
  font-size: 13px;
  color: var(--theme-danger, #b3413a);
}
.aiws-error__text .aiws-tool {
  margin-left: 8px;
}
.aiws-step {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 12px;
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 10px;
  background: var(--theme-surface-raised, #f2f5f4);
}
.aiws-step__ops {
  margin: 0;
  padding-left: 18px;
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.aiws-step__settled {
  font-size: 11.5px;
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-steps--live {
  flex-direction: column;
  align-items: stretch;
}
.aiws-warnings--rejected {
  color: var(--theme-text-secondary, #4b5f5c);
}
.aiws-artifact {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
}
.aiws-artifact strong {
  font-size: 13px;
}
.aiws-artifact small {
  font-size: 11px;
  color: var(--theme-text-tertiary, #7b8a88);
}

/* --- dock continuity: replay mark, error turn, questions, meta link --- */
.ask-dock__replay {
  display: inline-block;
  margin-left: 8px;
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
  border: 1px solid var(--theme-border-subtle, #d9dfde);
  border-radius: 999px;
  padding: 0 8px;
}
.ask-dock__errorTurn {
  margin-top: 4px;
  padding: 8px 12px;
  border-left: 3px solid var(--theme-danger, #b3413a);
  background: rgba(179, 65, 58, 0.07);
  border-radius: 0 8px 8px 0;
}
.ask-dock__errorTurn p {
  margin: 0 0 6px;
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__errorTurn code {
  margin-left: 8px;
  font-size: 10.5px;
  color: var(--theme-text-tertiary, #7b8a88);
}
.ask-dock__questions {
  margin-top: 8px;
  padding: 8px 12px;
  border-left: 3px solid var(--theme-warning, #c48d29);
  background: rgba(196, 141, 41, 0.08);
  border-radius: 0 8px 8px 0;
}
.ask-dock__questions p {
  margin: 0;
  font-size: 12.5px;
  color: var(--theme-text-primary, #1f2a29);
}
.ask-dock__meta-link {
  border: none;
  background: none;
  padding: 0;
  font: inherit;
  font-size: 11px;
  color: var(--theme-accent, #0f817a);
  cursor: pointer;
  text-decoration: underline;
}
.ask-dock__meta-link:hover {
  text-decoration: none;
}

/* Mobile: the dock is the customer/operator surface — full-width panel,
 * clear of the canvas inspector offset that only exists on desktop. */
@media (max-width: 640px) {
  .ask-dock,
  .ask-dock--canvas {
    right: 8px;
    bottom: 8px;
  }
  .ask-dock__panel {
    width: calc(100vw - 16px);
    max-height: 72vh;
  }
}

/* Bot welcome — the figure on first-open empty states. */
.ask-dock__welcome {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem 0.75rem 0.75rem;
  text-align: center;
}

.ui-empty-illustration {
  display: block;
  width: 192px;
  height: 96px;
  max-width: 100%;
  justify-self: center;
  margin-inline: auto;
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: square;
  stroke-linejoin: miter;
}
.ui-empty-illustration__paper {
  fill: var(--surface-sheet);
  stroke: var(--border-default);
}
.ui-empty-illustration__member {
  stroke: var(--canvas-member);
}
.ui-empty-illustration__ghost {
  stroke: var(--canvas-dim-line);
  stroke-width: 1;
  stroke-dasharray: 4 4;
}

.recovery-page {
  display: grid;
  place-items: center;
  min-height: 100vh;
  background: var(--bg-app);
  padding: var(--space-32px);
}
.recovery-sheet {
  background: var(--surface-sheet);
  border: 1px solid var(--border-default);
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 0 100%);
  padding: var(--space-32px);
  max-width: 28rem;
  width: 100%;
  display: grid;
  gap: var(--space-16px);
}
.recovery-sheet h1 {
  margin: 0;
  font-size: var(--type-title-l);
}
.recovery-sheet p {
  margin: 0;
  color: var(--text-secondary);
}
.connection-content[hidden] {
  display: none;
}
@media (max-width: 640px) {
  .recovery-page {
    padding: var(--space-16px);
  }
  .recovery-sheet {
    padding: var(--space-24px);
  }
  .recovery-sheet .ui-button {
    min-height: var(--density-loose);
  }
}

.ai-settings {
  scroll-margin-top: var(--space-4);
}
.ai-settings a:not(.ui-button),
.ai-work-list a:not(.ui-button) {
  color: var(--interactive);
}
.ai-routes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: 1px solid var(--line);
}
.ai-route {
  min-width: 0;
  padding: var(--space-4) 0;
  border-bottom: 1px solid var(--line);
}
.ai-route:nth-child(odd) {
  padding-right: var(--space-4);
}
.ai-route:nth-child(even) {
  padding-left: var(--space-4);
  border-left: 1px solid var(--line);
}
.ai-route-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-3);
}
.ai-route-heading h3,
.ai-month h3 {
  font-size: var(--type-title-m);
  font-weight: 600;
  margin: 0;
}
.ai-route-fields {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) minmax(160px, 2fr);
  gap: var(--space-3);
}
.ai-route-fields label,
.ai-budget {
  display: grid;
  gap: var(--space-1);
  font-size: var(--text-sm);
  min-width: 0;
}
.ai-route-fields input,
.ai-route-fields select,
.ai-budget input {
  width: 100%;
  min-width: 0;
  min-height: var(--control-height);
  padding: var(--space-1) var(--space-2);
  background: var(--surface-panel);
  color: var(--text-primary);
  border: 1px solid var(--line);
  border-radius: var(--r-1);
  font: inherit;
}
.ai-number {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.ai-requires-person {
  border-left: 2px solid var(--state-warning);
  padding-left: var(--space-2);
}
.ai-advanced {
  margin-top: var(--space-2);
}
.ai-advanced summary {
  cursor: pointer;
  padding-block: var(--space-1);
  color: var(--text-secondary);
}
.ai-month {
  padding-block: var(--space-4);
}
.ai-ledger {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: var(--space-3);
}
.ai-ledger dt {
  color: var(--text-secondary);
}
.ai-ledger dd {
  margin: var(--space-1) 0 0;
}
.ai-budget {
  max-width: 360px;
}
.ai-settings-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  align-items: center;
  padding-block: var(--space-2);
}
.ai-settings-actions .ui-button:disabled {
  opacity: 1;
  color: var(--text-secondary);
  background: var(--surface-panel);
  border-color: var(--line);
}
.ai-person-list {
  list-style: none;
  padding: 0;
}
.ai-person-list li {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  padding-block: var(--space-2);
  border-bottom: 1px solid var(--line);
}
.ai-work {
  padding-block: var(--space-3);
  border-bottom: 1px solid var(--line);
}
.ai-work header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-3);
}
.ai-work dl {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
}
.ai-work dd {
  margin: var(--space-1) 0 0;
}
@media (max-width: 1100px) {
  .ai-routes {
    grid-template-columns: minmax(0, 1fr);
  }
  .ai-route:nth-child(odd),
  .ai-route:nth-child(even) {
    padding-inline: 0;
    border-left: 0;
  }
  .ai-ledger {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 600px) {
  .ai-route-fields,
  .ai-ledger {
    grid-template-columns: minmax(0, 1fr);
  }
}

.mail-preview-frame {
