  flex-wrap: wrap;
}

.landing-hero__note {
  align-items: center;
  color: var(--theme-fg-muted);
  display: flex;
  font-size: 0.875rem;
  gap: 0.5rem;
  margin-top: 1.75rem;
}

.landing-hero__shot {
  margin: 0;
}

.landing-hero__shot img,
.landing-section__shot img {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  box-shadow: var(--sheet);
  display: block;
  height: auto;
  width: 100%;
}

.landing-hero__shot figcaption {
  color: var(--theme-fg-muted);
  font-size: 0.8rem;
  margin-top: 0.5rem;
  text-align: center;
}

.landing-sections {
  display: grid;
  gap: clamp(2.5rem, 6vw, 4.5rem);
  padding: 0 clamp(1rem, 4vw, 3rem) clamp(2.5rem, 6vw, 4.5rem);
}

.landing-section {
  align-items: center;
  display: grid;
  gap: clamp(1.25rem, 3vw, 2.5rem);
  grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
}

.landing-section--flip .landing-section__shot {
  order: 2;
}

.landing-section--flip .landing-section__copy {
  order: 1;
}

.landing-section__shot {
  margin: 0;
}

.landing-section__copy h2 {
  font-size: 1.5rem;
  margin: 0 0 0.75rem;
}

.landing-section__copy p {
  color: var(--theme-fg-secondary);
  line-height: 1.6;
  margin: 0;
}

.landing-assistant {
  align-items: center;
  border-top: 1px solid var(--theme-border-subtle);
  display: grid;
  gap: 1.5rem;
  grid-template-columns: auto minmax(0, 5fr) minmax(0, 6fr);
  padding: clamp(2rem, 5vw, 4rem) clamp(1rem, 4vw, 3rem);
}

.landing-assistant h2 {
  font-size: 1.25rem;
  margin: 0 0 0.5rem;
}

.landing-assistant p {
  color: var(--theme-fg-secondary);
  line-height: 1.6;
  margin: 0;
}

.landing-foot {
  align-items: center;
  border-top: 1px solid var(--theme-border-subtle);
  color: var(--theme-fg-muted);
  display: flex;
  font-size: 0.85rem;
  justify-content: space-between;
  padding: 1.25rem clamp(1rem, 4vw, 3rem);
}

@media (max-width: 860px) {
  .landing-hero,
  .landing-section,
  .landing-assistant {
    grid-template-columns: 1fr;
  }

  .landing-section--flip .landing-section__shot {
    order: 0;
  }

  .landing-hero__copy h1 {
    font-size: 1.85rem;
  }
}

* {
