.dashboard {
  display: grid;
  gap: 1.25rem;
  grid-template-columns: minmax(0, 7fr) minmax(19rem, 5fr);
  max-width: 120rem;
}
.dashboard-attention,
.dashboard-continue,
.dashboard-list {
  grid-column: 1;
}
.dashboard-ops {
  grid-column: 2;
  grid-row: 2 / span 10;
  align-self: start;
  background: var(--theme-surface-panel);
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
