.ui-trace dl > div {
  display: grid;
  gap: var(--space-4px);
}
.ui-trace dl > div {
  grid-template-columns: 1fr 1fr;
}
.ui-trace dd {
  margin: 0;
  font-family: var(--font-mono);
  overflow-wrap: anywhere;
}
.ui-trace__formula {
  font-family: var(--font-mono);
  white-space: pre-wrap;
}
.ui-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  clip-path: inset(50%);
  overflow: hidden;
  white-space: nowrap;
}
.ui-table-region {
  display: grid;
  gap: var(--space-8px);
  min-width: 0;
}
.ui-table-scroll {
  overflow: auto;
  max-width: 100%;
  max-height: 28rem;
}
.ui-table-scroll.is-virtual {
  max-height: 28rem;
  overflow-anchor: none;
}
.ui-data-table,
.ui-table {
  width: 100%;
  border-collapse: collapse;
}
.ui-data-table :is(th, td) {
  height: var(--table-row-height);
  border-bottom: 1px solid var(--border-subtle);
  padding: 0 var(--space-8px);
  text-align: left;
}
.ui-data-table th {
  position: sticky;
  top: 0;
  z-index: var(--z-sticky);
  background: var(--surface-panel);
  color: var(--text-secondary);
  font-size: var(--type-label);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.ui-data-table th button {
  border: 0;
  background: transparent;
  font: inherit;
  color: inherit;
  padding: 0;
  height: var(--control-height);
}
.ui-data-table .is-numeric {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.ui-data-table tr[data-selected] {
  background: var(--surface-selected);
  border-inline-start: 2px solid var(--interactive);
}
.ui-data-table tr:hover {
  background: var(--surface-hover);
}
.ui-table-selection {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-8px);
  padding: var(--space-4px);
  border-block: 1px solid var(--border-default);
}
.is-virtual .ui-data-table td {
  white-space: nowrap;
  max-width: 24rem;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pricing-page {
  color: var(--theme-text-primary);
  background: var(--theme-surface-page);
  max-width: 90rem;
  margin: auto;
}

.project-prices {
  min-width: 0;
}
.price-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 17rem;
  gap: var(--space-6);
  align-items: start;
}
.price-layout > section,
.price-reading {
  min-width: 0;
}
.price-reading__heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}
.price-reading__context,
.price-rounding,
.price-history__row p {
  color: var(--text-secondary);
  font-size: var(--type-body);
}
.price-reading h3 {
  margin: var(--space-6) 0 var(--space-3);
}
.price-comparison,
.price-drivers,
.price-positions table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--type-body);
}
.price-comparison th,
.price-comparison td,
.price-drivers th,
.price-drivers td,
.price-positions th,
.price-positions td {
  border-bottom: 1px solid var(--border-default);
  padding: var(--space-3);
  text-align: right;
  vertical-align: top;
}
.price-comparison th:first-child,
.price-drivers th:first-child,
.price-positions th:first-child,
.price-positions td:nth-child(2) {
  text-align: left;
}
.price-comparison thead,
.price-positions thead {
  color: var(--text-secondary);
}
.price-comparison small,
.price-positions small {
  font-size: var(--type-micro);
  line-height: var(--line-micro);
  display: block;
  margin-top: var(--space-1);
  color: var(--text-secondary);
}
.price-amount {
  display: inline-flex;
  gap: var(--space-1);
  align-items: center;
  justify-content: flex-end;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.pricing-page button.price-trace {
  padding: 0;
  width: 1.5rem;
  height: 1.5rem;
  min-height: 0;
  border: 1px solid var(--border-default);
  font-family: var(--font-mono);
  font-size: var(--type-micro);
  color: var(--text-secondary);
}
.price-unknown {
  color: var(--text-secondary);
  font-family: var(--font-mono);
}
.price-band {
  border-top: 1px solid var(--border-default);
  border-bottom: 1px solid var(--border-default);
  padding: var(--space-3) 0;
  margin: var(--space-4) 0;
}
.price-band svg {
  width: 100%;
  height: 2rem;
  overflow: visible;
}
.price-band path {
  stroke: var(--text-secondary);
  stroke-width: 0.3;
  fill: none;
}
.price-band circle {
  fill: var(--interactive);
}
.price-policy {
  color: var(--state-warning-ink);
}
.price-cascade {
  border-left: 2px solid var(--border-default);
  padding-left: var(--space-3);
}
.price-cascade__step,
.price-cascade__total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
}
.price-cascade__total {
  border-top: 1px solid var(--border-default);
}
.price-cascade__total:last-child {
  border-top: 2px solid var(--text-primary);
}
.price-controls {
  border-left: 1px solid var(--border-default);
  padding-left: var(--space-4);
  position: sticky;
  top: var(--space-4);
}
.pricing-page .price-controls form,
.pricing-page .price-controls section {
  border: 0;
  padding: 0;
  background: transparent;
  margin: 0;
}
.price-controls label {
  font-size: var(--type-body);
}
.price-controls a {
  color: var(--interactive);
}
.price-controls label:has(input[type="checkbox"]) {
  display: flex;
  align-items: center;
}
.price-controls textarea {
  background: var(--surface-panel);
  color: var(--text-primary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  min-height: 5rem;
  padding: var(--space-2);
  font: inherit;
  resize: vertical;
  width: 100%;
  box-sizing: border-box;
}
.price-controls input[type="range"] {
  padding: 0;
  accent-color: var(--interactive);
}
.price-controls details {
  border-top: 1px solid var(--border-default);
  padding-top: var(--space-3);
}
.price-controls details label {
  margin-top: var(--space-2);
}
.price-positions {
  max-width: 100%;
}
.price-positions table {
  table-layout: fixed;
  font-size: var(--type-dense);
}
.price-positions th:first-child {
  width: 2rem;
}
.price-positions th:nth-child(2),
.price-positions th:nth-child(3) {
  width: 18%;
}
.price-positions .price-amount {
  flex-wrap: wrap;
  max-width: 100%;
  white-space: normal;
}
.price-positions .price-amount > span {
  white-space: nowrap;
}
.price-positions details {
  text-align: left;
}
.price-positions td {
  overflow-wrap: anywhere;
  white-space: normal;
}
.price-positions td:has(details) {
  white-space: normal;
}
.price-positions td:has(details) td {
  white-space: normal;
}
.price-history {
  border-top: 2px solid var(--border-default);
  margin-top: var(--space-64px);
  padding-top: var(--space-4);
}
.pricing-page .price-history__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  border: 0;
  border-bottom: 1px solid var(--border-default);
  border-radius: 0;
  padding: var(--space-3) 0;
  margin: 0;
  background: transparent;
}
.price-history__row > div > span,
.price-history__row strong + strong {
  margin-left: var(--space-3);
}
.price-history__row p {
  margin-bottom: 0;
  overflow-wrap: anywhere;
}
.price-error {
  border-left: 2px solid var(--danger);
  padding: var(--space-3);
}
.price-error button {
  margin-left: var(--space-3);
}
@media (max-width: 1100px) {
  .price-layout {
    grid-template-columns: minmax(0, 1fr) 15rem;
    gap: var(--space-3);
  }
  .price-comparison th,
  .price-comparison td {
    padding: var(--space-2) var(--space-1);
  }
}
@media (max-width: 1280px) {
  .price-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .price-controls {
    position: static;
    border-left: 0;
    border-top: 1px solid var(--border-default);
    padding: var(--space-4) 0 0;
  }
  .pricing-page .price-controls form {
    grid-template-columns: minmax(0, 1fr);
  }
  .price-controls h2,
  .price-controls p,
  .price-controls button,
  .price-controls a {
    grid-column: 1 / -1;
  }
}
.price-control-entry {
  grid-row: 1;
}
.price-control-drawer .price-controls {
  position: static;
  border: 0;
  padding: 0;
}
.price-control-drawer {
  background: var(--surface-panel);
}
.price-loading {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}
.price-positions th {
  position: sticky;
  top: 0;
  background: var(--surface-panel);
}
.price-comparison td,
.price-positions td:nth-child(n + 3),
.price-positions th:first-child,
.price-history__row strong:first-child {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
@media (max-width: 850px) {
  .price-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .price-controls {
    position: static;
    border-left: 0;
    border-top: 1px solid var(--border-default);
    padding: var(--space-3) 0 0;
  }
  .price-comparison {
    font-size: var(--type-micro);
  }
  .price-history__row {
    flex-wrap: wrap;
  }
  .pricing-page .price-controls form {
    grid-template-columns: minmax(0, 1fr);
  }
}
.pricing-page h1,
.pricing-page h2 {
  margin-bottom: 0.75rem;
}
.pricing-page header p {
  color: var(--theme-text-secondary);
}
.pricing-services-link {
  color: var(--interactive);
}
.pricing-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 1rem 0;
}
.pricing-tabs [aria-pressed="true"] {
  outline: 2px solid var(--theme-accent);
}
.pricing-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(18rem, 1fr);
  gap: 1.5rem;
}
.pricing-page article,
.pricing-page form {
  border: 1px solid var(--theme-border-subtle);
  padding: 1rem;
  background: var(--theme-surface-panel);
  border-radius: var(--radius-sm);
  margin: 0.75rem 0;
}
.pricing-page form {
  display: grid;
  gap: 0.75rem;
  align-content: start;
}

/* Column-mapping + separator fields pair up — a single tall column read as
 * a record viewer, not an import workspace. */
.pricing-page .form-grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (max-width: 700px) {
  .pricing-page .form-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

.pricing-page label {
  display: grid;
  gap: 0.3rem;
}
.pricing-page input,
.pricing-page select {
  background: var(--theme-surface-panel);
  color: var(--theme-text-primary);
  border: 1px solid var(--theme-border-subtle);
  padding: 0.6rem;
  border-radius: 0.25rem;
  min-width: 0;
}
.pricing-page input[type="checkbox"] {
  width: 1.25rem;
  height: 1.25rem;
}
.pricing-page button {
  padding: 0.55rem 0.8rem;
  cursor: pointer;
}
.pricing-page button:disabled {
  cursor: wait;
  opacity: 0.6;
}
.pricing-page [role="alert"] {
  color: var(--theme-danger);
}
.pricing-page dl div {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid var(--theme-border-subtle);
  padding: 0.3rem 0;
}
.pricing-page dd {
  margin: 0;
  overflow-wrap: break-word;
}
.pricing-page table {
  width: 100%;
  border-collapse: collapse;
}
.pricing-page td,
.pricing-page th {
  padding: 0.5rem;
  border-bottom: 1px solid var(--theme-border-subtle);
  text-align: right;
}
.pricing-page th:first-child,
.pricing-page td:nth-child(2),
.pricing-page .price-positions td:has(details) {
  text-align: left;
}
.pricing-page .price-positions th,
.pricing-page .price-positions td {
  padding: var(--space-2) var(--space-1);
}
.pricing-page .price-composition th {
  position: static;
  width: auto;
}
.pricing-page .price-composition th:first-child,
.pricing-page .price-composition td:first-child {
  width: 48%;
  text-align: left;
  font-family: var(--font-sans);
}
.pricing-page .price-composition th:nth-child(2),
.pricing-page .price-composition td:nth-child(2) {
  width: 18%;
  text-align: right;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.pricing-page .price-composition th:nth-child(3) {
  width: auto;
}
.pricing-page .price-comparison td,
.pricing-page .price-drivers td {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.pricing-page .ui-page-header h1 {
  font-size: var(--type-title-l);
  line-height: var(--line-title-l);
}
.pricing-import {
  overflow-x: auto;
}
@media (max-width: 760px) {
  .pricing-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .pricing-page {
    padding: 0.75rem;
  }
}

.pricing-extras {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  margin: var(--space-2) 0;
  padding: var(--space-2) var(--space-3);
}

.pricing-extras legend {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 0 0.25rem;
  text-transform: uppercase;
}

.pricing-extras__row {
  align-items: center;
  display: grid;
  gap: 0.5rem;
  grid-template-columns: minmax(7rem, 10rem) minmax(0, 1fr) minmax(6rem, 9rem) auto;
  margin-top: 0.375rem;
}

@media (max-width: 760px) {
  .pricing-extras__row {
    grid-template-columns: 1fr 1fr;
  }
}

.status-chip[data-status="pending"] {
  background: var(--theme-warning-soft, rgba(217, 119, 6, 0.12));
  color: var(--theme-warning);
}

.status-chip[data-status="applied"] {
  background: var(--theme-accent-soft, rgba(37, 99, 235, 0.12));
  color: var(--theme-accent);
}

.status-chip[data-status="rejected"] {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}

.status-chip[data-status="withdrawn"] {
  background: var(--theme-surface-alt, rgba(100, 116, 139, 0.12));
  color: var(--theme-text-secondary);
}

.field-hint {
  color: var(--theme-text-secondary);
  font-size: 0.72rem;
  margin: 0.15rem 0 0;
}

.coverage-summary {
  color: var(--theme-text-secondary);
  font-size: 0.8125rem;
  margin: 0;
}

.link-button {
  background: none;
  border: none;
  color: var(--theme-accent);
  cursor: pointer;
  font: inherit;
  padding: 0;
  text-decoration: underline;
}

.coverage-card {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  display: grid;
  gap: 0.25rem;
  padding: 0.75rem 1rem;
}

.coverage-card--missing {
  border-color: var(--theme-danger);
}

.coverage-card__meta,
.coverage-card > span {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
}

.coverage-card .status-chip {
  justify-self: start;
}

.audit-card {
  border: 1px solid var(--theme-border-subtle);
  border-radius: var(--r-2);
  display: grid;
  gap: 0.375rem;
  padding: 0.75rem 1rem;
}

.audit-card__header {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.audit-card__project {
  color: var(--theme-text-secondary);
  font-size: 0.75rem;
  margin-left: auto;
}

.audit-card__title {
  font-size: 0.875rem;
  margin: 0;
}

.audit-card__diffs {
  font-size: 0.75rem;
  margin: 0;
  padding-left: 1rem;
}

.audit-card__diffs code {
  color: var(--theme-text-secondary);
}

.audit-card__diffs span {
  color: var(--theme-text-secondary);
}

.audit-card__footer {
  color: var(--theme-text-secondary);
  display: flex;
  flex-wrap: wrap;
  font-size: 0.75rem;
  gap: 0.75rem;
}

.pricing-fix {
  font-weight: 600;
}
.pricing-demo-costs {
  border-block: 1px solid var(--border);
  padding-block: var(--space-3);
  margin-block: var(--space-3);
}
.pricing-demo-costs summary {
  cursor: pointer;
  font-weight: 600;
}
.pricing-demo-rows {
  display: grid;
  max-height: 24rem;
  overflow-y: auto;
}
.pricing-demo-rows > div {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  padding-block: var(--space-2);
  border-bottom: 1px solid var(--border);
}
.pricing-demo-rows span {
  overflow-wrap: anywhere;
}
.pricing-demo-rows strong {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
